from typing import List

def solve(data: dict) -> bool:
    # Edge case: if the list is empty, return True
    if not data['nums']:
        return True

    # Calculate the total sum of the numbers
    total_sum = sum(data['nums'])

    # If the total sum is odd, it cannot be split into two equal subsets
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2

    # Check if there exists a subset of numbers that sums up to the target sum
    return can_partition(data['nums'], target_sum)

def can_partition(nums: List[int], target: int) -> bool:
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: there is always a subset that sums up to 0 (by choosing no elements)
    dp[0][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(target + 1):
            if j >= nums[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][target]

